insert into public.dialogues (key, speaker_external_id, source_path, source_metadata) select key, speaker_external_id, source_path, source_metadata from jsonb_to_recordset($seed$[{"key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s01","speaker_external_id":"Benny the Builder","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s04","speaker_external_id":"Benny the Builder","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_missing_verbs_q02_the_confused_guard_s01","speaker_external_id":"Main Gate Gaurd 1","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_missing_verbs_q02_the_confused_guard_s04","speaker_external_id":"Main Gate Gaurd 1","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_missing_verbs_q03_don_t_let_him_guess_s01","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}},{"key":"missing_verbs_missing_verbs_q03_don_t_let_him_guess_turn_in","speaker_external_id":"Cannoneer","source_path":"_registry\\dialogues\\missing_verbs.yaml","source_metadata":{}}]$seed$::jsonb) as entries(key text, speaker_external_id text, source_path text, source_metadata jsonb) on conflict (key) do update set speaker_external_id = excluded.speaker_external_id, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s01","locale":"he","line_order":0,"content":"Hey! Over here! I need your help! היי! לכאן! אני צריך את העזרה שלך!","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s01","locale":"he","line_order":1,"content":"I have wood, tools and workers, but nobody knows what to DO. יש לי עצים, כלים ועובדים, אבל אף אחד לא יודע מה לעשות.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s01","locale":"he","line_order":2,"content":"Look at this order:___the wall. תראה את הפקודה:___את החומה.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s01","locale":"he","line_order":3,"content":"פועל = Verb הוא an action word - מילת פעולה Help me restore the missing verbs! עזרו לי לשחזר את הפעלים החסרים!","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s04","locale":"he","line_order":0,"content":"You're back! Let's see what you found. חזרת! בוא נראה מה מצאת.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s04","locale":"he","line_order":1,"content":"BUILD the wall! Now the workers know what to do. BUILD לִבנוֹת את החומה! עכשיו הפועלים יודעים מה לעשות - לִבנוֹת","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s04","locale":"he","line_order":2,"content":"Great job! You restored the missing verbs. כל הכבוד! שחזרתם את הפועל החסר.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q01_benny_can_t_build_s04","locale":"he","line_order":3,"content":"These orders came from the castle. Check the Gate Guard next. הפקודות הגיעו מהטירה. תבדקו את שומר השער.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q02_the_confused_guard_s01","locale":"he","line_order":0,"content":"Oh! The royal order is missing an action word. אוי! בפקודה חסרה מילת פעולה.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q02_the_confused_guard_s01","locale":"he","line_order":1,"content":"The knight must___the gate. האביר חייב___את השער.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q02_the_confused_guard_s01","locale":"he","line_order":2,"content":"Choose the action word. בחרו את מילת הפעולה.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q02_the_confused_guard_s01","locale":"he","line_order":3,"content":"Go to the training ground and find the missing verbs. לך למגרש האימונים ומצא את הפעלים החסרים.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q02_the_confused_guard_s04","locale":"he","line_order":0,"content":"You're back! חזרת! OPEN the gate - פתחו את השער HELP the king - עזור למלך","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q02_the_confused_guard_s04","locale":"he","line_order":1,"content":"JUMP over the box - קפיצה מעל הקופסה FIND the treasure - מצא את האוצר עכשיו הפקודות הגיוניות!","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q02_the_confused_guard_s04","locale":"he","line_order":2,"content":"עכשיו תבדקו את Cannoneer לפני שהוא מנחש מה לעשות עם התותח.","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q03_don_t_let_him_guess_s01","locale":"he","line_order":0,"content":"אה! מילת הפעולה נעלמה. אולי אני צריך לחבק את התותח? תעזור לי לשחזר את הפועל האמיתי!","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q03_don_t_let_him_guess_turn_in","locale":"he","line_order":0,"content":"FIRE the cannon! You restored the final verb. ירית בתותח ושחזרת את הפועל האחרון!","line_format":"plain_text"},{"dialogue_key":"missing_verbs_missing_verbs_q03_don_t_let_him_guess_turn_in","locale":"he","line_order":1,"content":"פועל מתאר פעולה - עכשיו הממלכה יכולה לעבוד שוב! וכל אחד מאנשי הממלכה יודע בדיוק איזה פעולה לעשות!    תודה רבה לכם!","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
